const UILanguage = React.createContext("en");
export function uiLanguage(language) {
  const lang = String(language || "en").toLowerCase().split(/[-_]/)[0];
  return Object.prototype.hasOwnProperty.call(UI_TRANSLATIONS,lang) ? lang : "en";
}
export function translateUI(text, language) {
  if (typeof text !== "string") return text;
  const lang = uiLanguage(language);
  if (lang === "en") return text;
  const key = text.replace(/\s+/g," ").trim();
  const translated = UI_TRANSLATIONS[lang][key];
  if (translated) return text.replace(text.trim(),translated);
  const fmt = UI_FORMATS[lang];
  if (/^(?:720p|768p|Pro resolution) · \d+–10 seconds$/.test(key)) return key.replace("Pro resolution",fmt[1]).replace("seconds",fmt[0]);
  if (key.endsWith(" — example camera framing")) return translateUI(key.replace(" — example camera framing",""),lang) + fmt[2];
  const duration = key.match(/^(.*?) needs a whole-number length from (\d+) to 10 seconds\.$/);
  if (duration) return fmt[3].replace("{model}",duration[1]).replace("{min}",duration[2]);
  return text;
}
export function localizeUI(node, language) {
  if (typeof node === "string") return translateUI(node,language);
  if (Array.isArray(node)) return node.map(child => localizeUI(child,language));
  if (!React.isValidElement(node)) return node;
  // These fields contain user data or exact provider requests, never UI copy.
  if (["pre","textarea","input"].includes(node.type)) {
    const props = {};
    for (const name of ["placeholder","aria-label","alt","title"]) if (node.props[name]) props[name] = translateUI(node.props[name],language);
    return React.cloneElement(node,props);
  }
  if (typeof node.type !== "string" && node.type !== React.Fragment) return node;
  const props = {};
  for (const name of ["aria-label","alt","title"]) if (node.props[name]) props[name] = translateUI(node.props[name],language);
  const children = localizeUI(node.props.children,language);
  return React.cloneElement(node,props,...(Array.isArray(children) ? children : [children]));
}

