export function nativeGenerationRequest(j, command) {
  const uploads = {};
  const slots = new Map();
  const bind = value => {
    if (typeof value === "string" && value.startsWith("multicam-resource:")) {
      const resourceId = value.slice("multicam-resource:".length);
      if (!resourceId) throw new Error("operation_failed");
      if (!slots.has(resourceId)) {
        const slot = "media" + slots.size; slots.set(resourceId,slot);
        uploads[slot] = {resourceId};
      }
      return "selects-input:" + slots.get(resourceId);
    }
    if (Array.isArray(value)) return value.map(bind);
    if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([k,v])=>[k,bind(v)]));
    return value;
  };
  const input = bind(command.params.input);
  return {scope:{libraryId:j.plan.libraryId,projectId:j.plan.projectId},
    key:j.id + (j.task === "lipsync" ? "-sync" : "-angle"),
    modelId:command.modelId,input,uploads,outputName:command.params.outputName,batch:1,
    origin:{tool:"video",tab:"multicam",recipeId:"multicam-generator"}};
}
export function generationInput(j, videoUrl) {
  const model = jobModel(j);
  validateModelDuration(model.key, j.plan?.settings?.duration);
  if (model.key === "omni11") return {prompt:j.prompt,video_url:videoUrl,resolution:"720p"};
  const urls = j.referenceUrls;
  if (j.identityVersion !== 1 || !Array.isArray(urls) || urls.length !== 3 ||
      urls.some(u => typeof u !== "string" || !u) || new Set(urls).size !== 3)
    throw new Error("identity_reference_missing");
  if (["legacy-kling","kling3"].includes(model.key)) return {prompt:j.prompt, video_url:videoUrl, keep_audio:false,
    elements:[{frontal_image_url:urls[0], reference_image_urls:urls.slice(1)}],
    ...(model.key === "kling3" ? {duration:String(j.plan.settings.duration),aspect_ratio:"auto"} : {})};
  if (model.key === "wan3" || model.key === "minimaxh3") return {
    prompt:j.prompt,reference_video_urls:[videoUrl],reference_image_urls:urls,
    duration:j.plan.settings.duration,resolution:model.key === "minimaxh3" ? "768P" : "720p",aspect_ratio:"adaptive",
    ...(model.key === "wan3" ? {audio:false} : {})};
  return {prompt:j.prompt, video_urls:[videoUrl], image_urls:urls, resolution:"720p",
    duration:model.editing ? "auto" : String(j.plan.settings.duration), aspect_ratio:"auto", generate_audio:false,
    ...(model.editing ? {task:"editing",bitrate_mode:"standard"} : {})};
}
export function validate(duration, angle, notes, customAngle = "") {
  if (!Number.isFinite(duration) || duration < 3 || duration > 10)
    throw new Error("Choose a length from 3 to 10 seconds.");
  cameraRequest(angle, customAngle);
  if (notes.length > 500)
    throw new Error("Keep your additional request under 500 characters.");
}
export function parseReply(text) {
  try {
    return JSON.parse(
      text
        .trim()
        .replace(/^```(?:json)?\s*/, "")
        .replace(/\s*```$/, ""),
    );
  } catch {
    throw new Error("response_unreadable");
  }
}
// Local diagnostics only: no media, prompts, credentials or response bodies.
export async function writeLocalDiagnostic(sdk, event) {
  const clean = (v) => safeDetail(v)
    .replace(/AIza[\w-]+/g, "[redacted]")
    .replace(/((?:api[_ -]?key|token|secret|password)\s*[:=]\s*)[^\s,;]+/gi, "$1[redacted]");
  const entry = {
    at: event.at || new Date().toISOString(),
    phase: clean(event.phase), step: clean(event.step), cause: clean(event.cause),
    jobId: event.jobId || null, generationId: event.generationId || null,
  };
  const payload = JSON.stringify(JSON.stringify(entry));
  const program = `import os,json,pathlib
root=os.environ.get("SELECTS_USER_PANELS_ROOT")
if not root: raise RuntimeError("Panel storage root unavailable")
p=pathlib.Path(root).parent / "logs" / "multicam-generator.jsonl"
p.parent.mkdir(parents=True,exist_ok=True)
if p.exists() and p.stat().st_size > 1048576:
 p.replace(p.with_suffix(".previous.jsonl"))
with p.open("a",encoding="utf-8") as f:
 f.write(json.dumps(json.loads(${payload}),ensure_ascii=False)+"\\n")
os.chmod(p,0o600)
`;
  const r = await sdk.runShell({
    summary: "Save local diagnostic",
    command: "python3 - <<'MC_DIAGNOSTIC'\n" + program + "\nMC_DIAGNOSTIC",
    timeoutMs: 10000, maxOutputBytes: 1024,
  });
  if (r.isError || r.exitCode !== 0) throw new Error("Local diagnostic write failed");
}

// The Selects host clamps panel calls to five minutes.
export const AI_TIMEOUT_MS = 300000;
export function isTransientFailure(error) {
  return /response_unreadable|errorServerUnavailable|generation_request_failed|fetch failed|network|connection|sse idle timeout|timed? ?out|timeout|did not finish within/i.test(String(error?.message || error));
}
export async function retryRead(operation, stillCurrent, pause = (ms) => new Promise((r) => setTimeout(r, ms))) {
  try { return await operation(); }
  catch (error) {
    if (!isTransientFailure(error) || !stillCurrent()) throw error;
    await pause(3000);
    if (!stillCurrent()) throw new Error("context_changed");
    return await operation();
  }
}
export function runGenerationCall(command, execute, stillCurrent, pause) {
  const readOnly = ["models.list", "models.schema", "queue.result", "queue.status"].includes(command.method);
  return readOnly ? retryRead(execute, stillCurrent, pause) : execute();
}
export function safeDetail(value) {
  return String(value || "Unknown error")
    .replace(/https?:\/\/[^\s"<>]+/g, "[URL redacted]")
    .replace(/(Bearer\s+)[^\s]+/gi, "$1[redacted]")
    .slice(0, 2000);
}
export function elapsedLabel(ms) {
  const seconds = Math.max(0, Math.floor(ms / 1000));
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
}
